using CommunityOS.Domain.Common;

namespace CommunityOS.Domain.Maintenance;

/// <summary>
/// A maintenance work order against an <see cref="Asset"/> (Req 36.1–36.5): the unit of maintenance
/// work a Facility Manager tracks from raise through assignment to completion. A work order is
/// either <b>preventive</b> (generated by the background sweep from a <see cref="MaintenancePlan"/>
/// when a scheduled occurrence falls due, Req 36.1) or <b>corrective</b> (raised directly by a user,
/// e.g. from a resolved ticket or ad-hoc, Req 36.2). Carries its owning
/// <see cref="TenantOwnedEntity.CommunityId"/>.
///
/// <para><b>Community infrastructure, NOT resident self-view data.</b> Like <see cref="Asset"/> /
/// <see cref="MaintenancePlan"/>, a work order belongs to the community, so it is a
/// <see cref="TenantOwnedEntity"/> deliberately NOT <see cref="IUnitScoped"/> — a Facility-Manager
/// register bounded by the community (the tenant global filter), not pinned to one unit.</para>
///
/// <para><b>Configurable classification + status state machine (steering: no hardcoding, Req 36.1,
/// 36.2).</b> <see cref="WorkOrderType"/> resolves against the editable <c>Work_Order_Type</c> list
/// (preventive / corrective), <see cref="Priority"/> against <c>Work_Order_Priority</c>, and
/// <see cref="Status"/> against <c>Work_Order_Status</c> (starting <see cref="WorkOrderStatuses.Open"/>
/// on creation). Transitions are validated against the editable <c>Work_Order_Status_Transition</c>
/// allow-list exactly like <c>Ticket_Status_Transition</c> / <c>Parcel_Status_Transition</c> — no
/// hardcoded transition table. All stored as stable codes, never frozen enums.</para>
///
/// <para><b>Assignment + notification (Req 36.3).</b> <see cref="AssignedToUserId"/> /
/// <see cref="AssignedAtUtc"/> record the maintenance-staff assignee; assignment goes through the
/// status allow-list to <see cref="WorkOrderStatuses.Assigned"/> and enqueues a
/// <c>work-order.assigned</c> push to the assignee via the transactional outbox — mirrors
/// <c>Ticket</c> assignment.</para>
///
/// <para><b>Completion → equipment history (Req 36.5).</b> On the transition into
/// <see cref="WorkOrderStatuses.Completed"/> the service stamps <see cref="CompletedAtUtc"/> and
/// appends a single, append-only <see cref="EquipmentHistoryEntry"/> to the asset's history. Parts
/// and labour are child <see cref="WorkOrderPart"/> / <see cref="WorkOrderLabour"/> rows (Req 36.4).</para>
///
/// <para>Derives from <see cref="TenantOwnedEntity"/>: tenant + soft-delete global filter, rowversion
/// concurrency token (so the assignment / status transitions record exactly once, Req 22.4), audit
/// columns.</para>
/// </summary>
public class WorkOrder : TenantOwnedEntity
{
    /// <summary>The asset this work order is for (Req 36.1, 36.2). Required.</summary>
    public Guid AssetId { get; set; }

    /// <summary>
    /// The <see cref="MaintenancePlan"/> that generated this work order when it is PREVENTIVE
    /// (Req 36.1), or null when it is CORRECTIVE (raised directly, Req 36.2). The link lets the
    /// completion history and reporting trace a preventive work order back to its schedule.
    /// </summary>
    public Guid? MaintenancePlanId { get; set; }

    /// <summary>
    /// Optional link to the helpdesk <c>Ticket</c> a corrective work order was raised from (Req 36.2),
    /// or null for an ad-hoc corrective / any preventive work order. Just a reference; no FK coupling
    /// into the Helpdesk module beyond the id.
    /// </summary>
    public Guid? SourceTicketId { get; set; }

    /// <summary>Short title/summary of the work (Req 36.2). Required.</summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>Free-text description of the work to be performed (Req 36.2). Required.</summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>
    /// Configurable type code resolved against the <c>Work_Order_Type</c> master-data list
    /// (preventive / corrective, Req 36.1, 36.2). Stored as the stable code, never a frozen enum.
    /// </summary>
    public string WorkOrderType { get; set; } = string.Empty;

    /// <summary>
    /// Configurable priority code resolved against the <c>Work_Order_Priority</c> master-data list
    /// (Req 36.2). Stored as the stable code, never a frozen enum.
    /// </summary>
    public string Priority { get; set; } = string.Empty;

    /// <summary>
    /// Configurable status code resolved against the <c>Work_Order_Status</c> master-data list.
    /// Starts <see cref="WorkOrderStatuses.Open"/> on creation; the status state machine drives
    /// transitions through the <c>Work_Order_Status_Transition</c> allow-list. Stored as the stable
    /// code, never a frozen enum.
    /// </summary>
    public string Status { get; set; } = WorkOrderStatuses.Open;

    /// <summary>
    /// The maintenance-staff <c>User</c> the work order is currently assigned to (Req 36.3), or null
    /// while unassigned. Set when a user with the <c>Assign</c> permission assigns it; the assignee
    /// must be a staff user holding <c>Edit</c> on <c>WorkOrder</c> in the community (RBAC data,
    /// resolved by the service — no hardcoded recipient).
    /// </summary>
    public Guid? AssignedToUserId { get; set; }

    /// <summary>When the work order was (re)assigned to <see cref="AssignedToUserId"/> (Req 36.3), or null while unassigned.</summary>
    public DateTime? AssignedAtUtc { get; set; }

    /// <summary>
    /// When the work order was completed (Req 36.5), or null until it reaches
    /// <see cref="WorkOrderStatuses.Completed"/>. Stamped by the status lifecycle on the transition
    /// into completed, and the instant recorded on the asset's equipment-history entry.
    /// </summary>
    public DateTime? CompletedAtUtc { get; set; }

    /// <summary>
    /// The occurrence instant a PREVENTIVE work order was generated for (the plan's
    /// <c>NextDueAtUtc</c> at generation time, Req 36.1), or null for a corrective work order. Lets
    /// the work order reference its exact scheduled occurrence.
    /// </summary>
    public DateTime? ScheduledForUtc { get; set; }

    /// <summary>Optional free-text completion/resolution notes recorded when the work order is completed (Req 36.5).</summary>
    public string? CompletionNotes { get; set; }
}

/// <summary>
/// Well-known default <c>Work_Order_Status</c> codes (Req 36.1–36.5). Seeded master-data codes kept
/// as constants so the service sets/compares status without a magic string. <b>Data</b>, not a
/// behavioural enum — the status list AND the allowed transitions are editable master data; these
/// constants only name the seeded defaults.
/// </summary>
public static class WorkOrderStatuses
{
    /// <summary>Initial status on creation/generation (Req 36.1, 36.2): raised, not yet assigned.</summary>
    public const string Open = "open";

    /// <summary>Assigned to a maintenance-staff member (Req 36.3).</summary>
    public const string Assigned = "assigned";

    /// <summary>Work has started (Req 36.4).</summary>
    public const string InProgress = "in_progress";

    /// <summary>Waiting on a part / third party.</summary>
    public const string OnHold = "on_hold";

    /// <summary>The work is complete (Req 36.5); completion is appended to the asset's equipment history.</summary>
    public const string Completed = "completed";

    /// <summary>The work order was cancelled before completion.</summary>
    public const string Cancelled = "cancelled";
}

/// <summary>
/// Well-known default <c>Work_Order_Type</c> / <c>Work_Order_Priority</c> codes (Req 36.1, 36.2).
/// Seeded master-data codes kept as constants. <b>Data</b>, not behavioural enums — every list is
/// editable per community; these constants only name the seeded defaults.
/// </summary>
public static class WorkOrderClassification
{
    // Work_Order_Type defaults.
    public const string TypePreventive = "preventive";
    public const string TypeCorrective = "corrective";

    // Work_Order_Priority defaults.
    public const string PriorityLow = "low";
    public const string PriorityMedium = "medium";
    public const string PriorityHigh = "high";
    public const string PriorityUrgent = "urgent";
}
